sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float strength;

half4 main(float2 coord) {
    half4 current = image.eval(coord);
    float aCurrent = current.a;
    if (aCurrent < 1e-5) {
        return current;
    }
    half3 rgbCur = current.rgb / aCurrent;

    float rad = radians(angle);
    float2 dir = float2(cos(rad), sin(rad));
    float2 sampleCoord = coord + dir;

    half4 neighbor = image.eval(sampleCoord);
    half3 rgbNeighbor;
    float aNeighbor = neighbor.a;
    if (aNeighbor < 1e-5) {
        rgbNeighbor = half3(0.0);
    } else {
        rgbNeighbor = neighbor.rgb / aNeighbor;
    }

    half lumCur = dot(rgbCur, half3(0.299, 0.587, 0.114));
    half lumN = dot(rgbNeighbor, half3(0.299, 0.587, 0.114));
    half delta = lumN - lumCur;
    half val = 0.5 + delta * strength;
    val = clamp(val, 0.0, 1.0);

    half3 outRgb = half3(val);
    return half4(outRgb * aCurrent, aCurrent);
}
